// Первый экран «hero-centered»: центрированный оффер над фото кабинета; на телефоне — текст, затем фото.
// Крупная типографика Lora, тёплое фото 3:2 снизу, вход rise при профиле calm (по мотивам каталога hero-centered).
import { srcSetOf } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

type Image = { src: string; alt: string };

export type HeroCenteredProps = {
  eyebrow: string;
  title: string;
  lead: string;
  note: string;
  image: Image;
};

function useEnter() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const on = lively && !reduce;
  return (step: number) =>
    on
      ? {
          initial: { opacity: 0, y: 16 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.6, delay: step * 0.08, ease: [0.23, 1, 0.32, 1] as const },
        }
      : {};
}

export default function HeroCentered({ eyebrow, title, lead, note, image }: HeroCenteredProps) {
  const enter = useEnter();
  return (
    <LazyMotion features={domAnimation}>
      <section
        data-wz-component="Hero"
