// «Как проходит запись»: четыре шага сценария как пронумерованные строки с крупными цифрами Lora —
// асимметричная сетка: номер слева, текст справа; на телефоне — в одну колонку.
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

type Step = { title: string; text: string };

export type HowItWorksProps = {
  title: string;
  intro?: string;
  items: Step[];
};

function useReveal() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const on = lively && !reduce;
  return () =>
    on
      ? {
          initial: { opacity: 0, y: 16 },
          whileInView: { opacity: 1, y: 0 },
          viewport: { once: true, margin: "0px 0px -80px 0px" },
          transition: { duration: 0.5, ease: [0.23, 1, 0.32, 1] as const },
        }
      : {};
}

export default function HowItWorks({ title, intro, items }: HowItWorksProps) {
