            </li>
          ))}
        </ul>
        <p className="mt-12">
          <a
            href="#form"
            className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-inverse px-6 text-center text-body font-bold text-inverse-foreground transition-transform duration-200 hover:-translate-y-0.5 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
          >
